#include <iostream>
#include <string>
using namespace std;

enum class Level { INFO, WARN, ERROR };

class Logger {
public:
    static void log(Level level, const string& msg) {
        static const char* names[] = {"INFO", "WARN", "ERROR"};
        cout << "[" << names[(int)level] << "]: " << msg << endl;
    }

    static void info(const string& msg) { log(Level::INFO, msg); }
    static void warn(const string& msg) { log(Level::WARN, msg); }
    static void error(const string& msg) { log(Level::ERROR, msg); }
};

int main() {
    Logger::info("Application started");
    Logger::warn("Low memory");
    Logger::error("File not found");
    return 0;
}
